193	                        }
194	
195	                        // Create a new List for COW semantics
196	                        List<E> newEntries = new ArrayList<E>(entries.size() + 1);
197	                        int i = 0;
198	                        E replacedEntry = null;
199	                        do {
200	                            E entry = entries.get(i);
201	                            // Only add old entry if the address is not the same as the one we try to add as well.
202	                            // In this case we will skip it and just add the new entry as this may have
203	                            // more up-to-date data and cancel the old after we were able to update the cache.
204	                            if (!Cache.this.equals(e, entry)) {
205	                                newEntries.add(entry);
206	                            } else {
207	                                replacedEntry = entry;
208	                                newEntries.add(e);
209	
210	                                ++i;
211	                                for (; i < entries.size(); ++i) {
212	                                    newEntries.add(entries.get(i));
213	                                }
214	                                break;
215	                            }
216	                        } while (++i < entries.size());
217	                        if (replacedEntry == null) {
218	                            newEntries.add(e);
219	                        }
220	                        sortEntries(hostname, newEntries);
221	
222	                        if (compareAndSet(entries, Collections.unmodifiableList(newEntries))) {
223	                            return scheduleCacheExpirationIfNeeded(ttl, loop);
224	                        }
225	                    } else if (compareAndSet(entries, singletonList(e))) {
226	                        return scheduleCacheExpirationIfNeeded(ttl, loop);
227	                    }
228	                }
229	            } else {
230	                for (;;) {
231	                    List<E> entries = get();
232	                    if (compareAndSet(entries, singletonList(e))) {
233	                        return scheduleCacheExpirationIfNeeded(ttl, loop);
234	                    }
235	                }
236	            }
237	        }
238	
239	        private boolean scheduleCacheExpirationIfNeeded(int ttl, EventLoop loop) {
240	            for (;;) {
241	                // We currently don't calculate a new TTL when we need to retry the CAS as we don't expect this to
242	                // be invoked very concurrently and also we use SECONDS anyway. If this ever becomes a problem
243	                // we can reconsider.
244	                ScheduledFuture<?> oldFuture = FUTURE_UPDATER.get(this);
245	                if (oldFuture == CANCELLED) {
246	                    // This Entries was already evicted from resolveCache by a concurrent expiration.
247	                    // Signal the caller (cache()) to retry with a fresh Entries.
248	                    return false;
249	                }
250	                if (oldFuture == null || oldFuture.getDelay(TimeUnit.SECONDS) > ttl) {
251	                    ScheduledFuture<?> newFuture = loop.schedule(this, ttl, TimeUnit.SECONDS);
252	                    // It is possible that
253	                    // 1. task will fire in between this line, or
254	                    // 2. multiple timers may be set if there is concurrency
255	                    // (1) If the task fires and sets CANCELLED before our CAS, the next loop iteration returns false.
256	                    // (2) This is a trade-off to avoid concurrency resulting in contention on a synchronized block.
257	                    if (FUTURE_UPDATER.compareAndSet(this, oldFuture, newFuture)) {
258	                        if (oldFuture != null) {
259	                            oldFuture.cancel(true);
260	                        }
261	                        return true;
262	                    } else {
263	                        // There was something else scheduled in the meantime... Cancel and try again.
264	                        newFuture.cancel(true);
265	                    }
266	                } else {
267	                    return true;
268	                }
269	            }
270	        }
271	
272	        boolean clearAndCancel() {
273	            List<E> entries = getAndSet(Collections.<E>emptyList());
274	            if (entries.isEmpty()) {
275	                return false;
276	            }
277	
278	            ScheduledFuture<?> expirationFuture = FUTURE_UPDATER.getAndSet(this, CANCELLED);
279	            if (expirationFuture != null) {
280	                expirationFuture.cancel(false);
281	            }
282	
283	            return true;
284	        }
285	
286	        @Override
287	        public void run() {
288	            // We always remove all entries for a hostname once one entry expire. This is not the
289	            // most efficient to do but this way we can guarantee that if a DnsResolver
290	            // be configured to prefer one ip family over the other we will not return unexpected
291	            // results to the enduser if one of the A or AAAA records has different TTL settings.
292	            //
293	            // As a TTL is just a hint of the maximum time a cache is allowed to cache stuff it's
294	            // completely fine to remove the entry even if the TTL is not reached yet.
295	            //
296	            // See https://github.com/netty/netty/issues/7329
297	            resolveCache.remove(hostname, this);
298	
299	            clearAndCancel();
300	        }
301	    }
302	}
