16	package io.netty.handler.ssl;
17	
18	import io.netty.internal.tcnative.SSL;
19	import io.netty.util.AsciiString;
20	
21	import java.util.ArrayList;
22	import java.util.HashMap;
23	import java.util.HashSet;
24	import java.util.List;
25	import java.util.Map;
26	import java.util.Set;
27	
28	/**
29	 * {@link OpenSslSessionCache} that is used by the client-side.
30	 */
31	final class OpenSslClientSessionCache extends OpenSslSessionCache {
32	    private final Map<HostPort, Set<NativeSslSession>> sessions = new HashMap<>();
33	
34	    OpenSslClientSessionCache(OpenSslEngineMap engines) {
35	        super(engines);
36	    }
37	
38	    @Override
39	    protected boolean sessionCreated(NativeSslSession session) {
40	        assert Thread.holdsLock(this);
41	        HostPort hostPort = keyFor(session.getPeerHost(), session.getPeerPort());
42	        if (hostPort == null) {
43	            return false;
44	        }
45	        Set<NativeSslSession> sessionsForHost = sessions.get(hostPort);
46	        if (sessionsForHost == null) {
47	            // Let's start with something small as usually the server does not provide too many of these per hostPort
48	            // mapping.
49	            sessionsForHost = new HashSet<>(4);
50	            sessions.put(hostPort, sessionsForHost);
51	        }
52	        sessionsForHost.add(session);
53	        return true;
54	    }
55	
56	    @Override
57	    protected void sessionRemoved(NativeSslSession session) {
58	        assert Thread.holdsLock(this);
59	        HostPort hostPort = keyFor(session.getPeerHost(), session.getPeerPort());
60	        if (hostPort == null) {
61	            return;
62	        }
63	        Set<NativeSslSession> sessionsForHost = sessions.get(hostPort);
64	        if (sessionsForHost != null) {
65	            sessionsForHost.remove(session);
66	            if (sessionsForHost.isEmpty()) {
67	                sessions.remove(hostPort);
68	            }
69	        }
70	    }
71	
72	    @Override
73	    boolean setSession(long ssl, OpenSslInternalSession session, String host, int port) {
74	        HostPort hostPort = keyFor(host, port);
75	        if (hostPort == null) {
76	            return false;
77	        }
78	        final boolean reused;
79	        boolean singleUsed = false;
80	        long capturedCreationTime = 0;
81	        long capturedLastAccessedTime = 0;
82	        OpenSslSessionId capturedSessionId = null;
83	        Map<String, Object> capturedKeyValueStorage = null;
84	        synchronized (this) {
85	            Set<NativeSslSession> sessionsForHost = sessions.get(hostPort);
86	            if (sessionsForHost == null) {
87	                return false;
88	            }
89	            if (sessionsForHost.isEmpty()) {
90	                sessions.remove(hostPort);
91	                // There is no session that we can use.
92	                return false;
93	            }
94	
95	            NativeSslSession nativeSslSession = null;
96	            List<NativeSslSession> toBeRemoved = null;
97	            // Loop through all the sessions that might be usable and check if we can use one of these.
98	            for (NativeSslSession sslSession : sessionsForHost) {
99	                if (sslSession.isValid()) {
100	                    nativeSslSession = sslSession;
101	                    break;
102	                } else {
103	                    if (toBeRemoved == null) {
104	                        toBeRemoved = new ArrayList<>(2);
105	                    }
106	                    toBeRemoved.add(sslSession);
107	                }
108	            }
109	
110	            // Remove everything that is not valid anymore
111	            if (toBeRemoved != null) {
112	                for (NativeSslSession sslSession : toBeRemoved) {
113	                    removeSessionWithId(sslSession.sessionId());
114	                }
115	            }
116	            if (nativeSslSession == null) {
117	                // Couldn't find a valid session that could be used.
118	                return false;
119	            }
120	
121	            // Try to set the session, if true is returned OpenSSL incremented the reference count
122	            // of the underlying SSL_SESSION*.
123	            reused = SSL.setSession(ssl, nativeSslSession.session());
124	            if (reused) {
125	                singleUsed = nativeSslSession.shouldBeSingleUse();
126	                if (singleUsed) {
127	                    // Remove while holding the lock so no concurrent thread can pick up this single-use ticket.
128	                    removeSessionWithId(nativeSslSession.sessionId());
129	                } else {
130	                    // Capture all fields from the native session while holding the lock so a concurrent
131	                    // removeSessionWithId cannot free the session before we read from it.
132	                    long now = System.currentTimeMillis();
133	                    nativeSslSession.setLastAccessedTime(now);
134	                    capturedCreationTime = nativeSslSession.getCreationTime();
135	                    capturedLastAccessedTime = now;
136	                    capturedSessionId = nativeSslSession.sessionId();
137	                    capturedKeyValueStorage = nativeSslSession.keyValueStorage;
138	                }
139	            }
140	        }
141	
142	        if (reused) {
143	            if (singleUsed) {
144	                // The native session was already removed and freed inside the lock; don't touch it again.
145	                session.invalidate();
146	            } else {
147	                session.setSessionDetails(capturedCreationTime, capturedLastAccessedTime,
148	                        capturedSessionId, capturedKeyValueStorage);
149	            }
150	        }
151	        return reused;
152	    }
153	
154	    private static HostPort keyFor(String host, int port) {
155	        if (host == null && port < 1) {
156	            return null;
157	        }
158	        return new HostPort(host, port);
159	    }
160	
161	    @Override
162	    synchronized void clear() {
163	        super.clear();
164	        sessions.clear();
165	    }
166	
167	    /**
168	     * Host / Port tuple used to find a {@link OpenSslInternalSession} in the cache.
169	     */
170	    private static final class HostPort {
171	        private final int hash;
172	        private final String host;
173	        private final int port;
174	
175	        HostPort(String host, int port) {
176	            this.host = host;
177	            this.port = port;
178	            // Calculate a hashCode that does ignore case.
179	            this.hash = 31 * AsciiString.hashCode(host) + port;
180	        }
181	
182	        @Override
183	        public int hashCode() {
184	            return hash;
185	        }
186	
187	        @Override
188	        public boolean equals(Object obj) {
189	            if (!(obj instanceof HostPort)) {
190	                return false;
191	            }
192	            HostPort other = (HostPort) obj;
193	            return port == other.port &&
194	                    (host == null ? other.host == null : host.equalsIgnoreCase(other.host));
195	        }
196	
197	        @Override
198	        public String toString() {
199	            return "HostPort{" +
200	                    "host='" + host + '\'' +
201	                    ", port=" + port +
202	                    '}';
203	        }
204	    }
205	}
