@Override
boolean setSession(long ssl, OpenSslInternalSession session, String host, int port) {
    HostPort hostPort = keyFor(host, port);
    if (hostPort == null) {
        return false;
    }
    final boolean reused;
    boolean singleUsed = false;
    long capturedCreationTime = 0;
    long capturedLastAccessedTime = 0;
    OpenSslSessionId capturedSessionId = null;
    Map<String, Object> capturedKeyValueStorage = null;
    synchronized (this) {
        Set<NativeSslSession> sessionsForHost = sessions.get(hostPort);
        if (sessionsForHost == null) {
            return false;
        }
        if (sessionsForHost.isEmpty()) {
            sessions.remove(hostPort);
            // There is no session that we can use.
            return false;
        }

        NativeSslSession nativeSslSession = null;
        List<NativeSslSession> toBeRemoved = null;
        // Loop through all the sessions that might be usable and check if we can use one of these.
        for (NativeSslSession sslSession : sessionsForHost) {
            if (sslSession.isValid()) {
                nativeSslSession = sslSession;
                break;
            } else {
                if (toBeRemoved == null) {
                    toBeRemoved = new ArrayList<>(2);
                }
                toBeRemoved.add(sslSession);
            }
        }

        // Remove everything that is not valid anymore
        if (toBeRemoved != null) {
            for (NativeSslSession sslSession : toBeRemoved) {
                removeSessionWithId(sslSession.sessionId());
            }
        }
        if (nativeSslSession == null) {
            // Couldn't find a valid session that could be used.
            return false;
        }

        // Try to set the session, if true is returned OpenSSL incremented the reference count
        // of the underlying SSL_SESSION*.
        reused = SSL.setSession(ssl, nativeSslSession.session());
        if (reused) {
            singleUsed = nativeSslSession.shouldBeSingleUse();
            if (singleUsed) {
                // Remove while holding the lock so no concurrent thread can pick up this single-use ticket.
                removeSessionWithId(nativeSslSession.sessionId());
            } else {
                // Capture all fields from the native session while holding the lock so a concurrent
                // removeSessionWithId cannot free the session before we read from it.
                long now = System.currentTimeMillis();
                nativeSslSession.setLastAccessedTime(now);
                capturedCreationTime = nativeSslSession.getCreationTime();
                capturedLastAccessedTime = now;
                capturedSessionId = nativeSslSession.sessionId();
                capturedKeyValueStorage = nativeSslSession.keyValueStorage;
            }
        }
    }

    if (reused) {
        if (singleUsed) {
            // The native session was already removed and freed inside the lock; don't touch it again.
            session.invalidate();
        } else {
            session.setSessionDetails(capturedCreationTime, capturedLastAccessedTime,
                    capturedSessionId, capturedKeyValueStorage);
        }
    }
    return reused;
}

private static HostPort keyFor(String host, int port) {
    if (host == null && port < 1) {
        return null;
    }
    return new HostPort(host, port);
}

